// Loop over input items and add a new field called 'myNewField' to the JSON of each one
// Get the response from HTTP Request node
const response = $input.first().json;
const bodyText = response.body || response.data || JSON.stringify(response);

function parseCSV(str) {
  const lines = str.trim().split('\n');
  const headers = lines[0].split(',').map(h => h.trim().replace(/"/g, ''));
  return lines.slice(1).map(line => {
    const vals = line.split(',');
    const obj = {};
    headers.forEach((h, i) => obj[h] = vals[i] ? vals[i].trim().replace(/"/g, '') : '');
    return obj;
  });
}

const rows = parseCSV(bodyText);

const total = rows.length;
const cancelled = rows.filter(r => r.order_status === 'Cancelled').length;
const cancellation_rate = total > 0 ? cancelled / total : 0;

const delTimes = rows
  .map(r => parseFloat(r.delivery_time_mins))
  .filter(v => !isNaN(v));
const avg_delivery_time = delTimes.length > 0
  ? delTimes.reduce((a, b) => a + b, 0) / delTimes.length
  : 0;

const zoneComplaints = {};
rows.forEach(r => {
  const z = r.delivery_zone;
  const c = parseInt(r.customer_complaints) || 0;
  zoneComplaints[z] = (zoneComplaints[z] || 0) + c;
});
const worst_zone = Object.entries(zoneComplaints)
  .sort((a, b) => b[1] - a[1])[0]?.[0] || 'N/A';

const restCancel = {};
rows.forEach(r => {
  if (r.order_status === 'Cancelled') {
    restCancel[r.restaurant_name] = (restCancel[r.restaurant_name] || 0) + 1;
  }
});
const worst_restaurant = Object.entries(restCancel)
  .sort((a, b) => b[1] - a[1])[0]?.[0] || 'N/A';

const riskPairs = {};
rows.filter(r => r.cancel_risk === 'high').forEach(r => {
  const key = `${r.restaurant_name} - ${r.delivery_zone}`;
  riskPairs[key] = (riskPairs[key] || 0) + 1;
});
const top_risk_pair = Object.entries(riskPairs)
  .sort((a, b) => b[1] - a[1])[0]?.[0] || 'N/A';

const today = new Date().toISOString().slice(0, 10);

return [{
  json: {
    total_orders: total,
    cancellation_rate: Math.round(cancellation_rate * 1000) / 1000,
    avg_delivery_time: Math.round(avg_delivery_time * 10) / 10,
    worst_zone,
    worst_restaurant,
    top_risk_pair,
    date: today
  }
}];

